import React, { useEffect, useRef, useState, useMemo } from 'react';
import L from 'leaflet';
import {
  MapPin,
  AlertTriangle,
  CheckCircle2,
  TrendingUp,
  Filter,
  RefreshCw,
  Eye,
  Info,
  Store,
  Compass,
  ArrowRight,
  ShieldCheck,
  Zap,
} from 'lucide-react';
import { Destination, District } from '../types/database';
import {
  GovCrowdStatus,
  GOV_CROWD_CONFIGS,
  getGovCrowdStatus,
  getDestinationIntelligenceRecords,
  DestinationIntelligenceRecord,
} from '../services/tourismIntelligence';
import { Badge } from './ui/badge';
import { Button } from './ui/button';
import { Card } from './ui/card';

interface CrowdIntelligenceMapProps {
  destinations: Destination[];
  districts: District[];
  onSelectDestination?: (destination: Destination) => void;
  navigate?: (path: string) => void;
}

export function CrowdIntelligenceMap({
  destinations,
  districts,
  onSelectDestination,
  navigate,
}: CrowdIntelligenceMapProps) {
  const mapContainerRef = useRef<HTMLDivElement | null>(null);
  const mapInstanceRef = useRef<L.Map | null>(null);
  const markersGroupRef = useRef<L.LayerGroup | null>(null);
  const zonesGroupRef = useRef<L.LayerGroup | null>(null);

  const [crowdFilter, setCrowdFilter] = useState<'ALL' | GovCrowdStatus>('ALL');
  const [selectedDistrictId, setSelectedDistrictId] = useState<string>('all');
  const [selectedRecord, setSelectedRecord] = useState<DestinationIntelligenceRecord | null>(null);
  const [showCarryingCapacityZone, setShowCarryingCapacityZone] = useState<boolean>(true);

  // Compute records
  const intelligenceRecords = useMemo(() => {
    return getDestinationIntelligenceRecords(destinations);
  }, [destinations]);

  // Filtered records
  const filteredRecords = useMemo(() => {
    return intelligenceRecords.filter((record) => {
      const matchCrowd = crowdFilter === 'ALL' || record.crowdStatus === crowdFilter;
      const matchDistrict =
        selectedDistrictId === 'all' || record.destination.district_id === selectedDistrictId;
      return matchCrowd && matchDistrict;
    });
  }, [intelligenceRecords, crowdFilter, selectedDistrictId]);

  // Initialize Map
  useEffect(() => {
    if (!mapContainerRef.current) return;

    if (!mapInstanceRef.current) {
      const map = L.map(mapContainerRef.current, {
        center: [23.6102, 85.2799], // Central Jharkhand coords
        zoom: 8,
        zoomControl: false,
        attributionControl: false,
      });

      L.tileLayer('https://{s}.basemaps.cartocdn.com/rastertiles/voyager/{z}/{x}/{y}{r}.png', {
        maxZoom: 19,
        subdomains: 'abcd',
      }).addTo(map);

      L.control.zoom({ position: 'bottomright' }).addTo(map);

      const zones = L.layerGroup().addTo(map);
      const markers = L.layerGroup().addTo(map);

      mapInstanceRef.current = map;
      zonesGroupRef.current = zones;
      markersGroupRef.current = markers;
    }

    return () => {
      if (mapInstanceRef.current) {
        mapInstanceRef.current.remove();
        mapInstanceRef.current = null;
      }
    };
  }, []);

  // Update Markers & Carrying Capacity Overlays
  useEffect(() => {
    const map = mapInstanceRef.current;
    const markersGroup = markersGroupRef.current;
    const zonesGroup = zonesGroupRef.current;

    if (!map || !markersGroup || !zonesGroup) return;

    markersGroup.clearLayers();
    zonesGroup.clearLayers();

    filteredRecords.forEach((record) => {
      const { destination, crowdStatus, crowdConfig } = record;
      const lat = destination.latitude;
      const lng = destination.longitude;

      if (!lat || !lng) return;

      // Color rules:
      // 🔴 RED = HIGH (#dc2626)
      // 🟢 GREEN = MEDIUM (#16a34a)
      // 🟡 DARK YELLOW = LOW (#d97706)
      const colorHex = crowdConfig.hexColor;

      // Carrying capacity zone radius
      if (showCarryingCapacityZone) {
        const radiusMeters =
          crowdStatus === 'HIGH' ? 3800 : crowdStatus === 'MEDIUM' ? 2600 : 1800;

        const circle = L.circle([lat, lng], {
          radius: radiusMeters,
          color: colorHex,
          fillColor: colorHex,
          fillOpacity: crowdStatus === 'HIGH' ? 0.22 : 0.15,
          weight: crowdStatus === 'HIGH' ? 2 : 1.5,
          dashArray: crowdStatus === 'LOW' ? '4, 4' : undefined,
        });

        circle.addTo(zonesGroup);
      }

      // Custom DivIcon with Pulse Effect
      const isHigh = crowdStatus === 'HIGH';
      const isLow = crowdStatus === 'LOW';

      const iconHtml = `
        <div class="relative flex items-center justify-center cursor-pointer group">
          ${
            isHigh
              ? `<div class="absolute -inset-2 rounded-full bg-red-500/40 animate-ping"></div>`
              : isLow
              ? `<div class="absolute -inset-1.5 rounded-full bg-amber-400/30 animate-pulse"></div>`
              : ''
          }
          <div class="relative flex items-center justify-center w-8 h-8 rounded-full shadow-lg border-2 border-white text-white font-extrabold text-[11px] transition-transform group-hover:scale-110" style="background-color: ${colorHex};">
            ${isHigh ? '🔴' : isLow ? '🟡' : '🟢'}
          </div>
          <div class="absolute -bottom-5 px-1.5 py-0.5 rounded bg-stone-900/90 text-white text-[9px] font-bold whitespace-nowrap shadow pointer-events-none">
            ${destination.name.split(' ')[0]}
          </div>
        </div>
      `;

      const customIcon = L.divIcon({
        html: iconHtml,
        className: 'gov-crowd-marker',
        iconSize: [32, 32],
        iconAnchor: [16, 16],
      });

      const marker = L.marker([lat, lng], { icon: customIcon });

      marker.on('click', () => {
        setSelectedRecord(record);
        if (onSelectDestination) {
          onSelectDestination(destination);
        }
        map.setView([lat, lng], 11, { animate: true });
      });

      marker.addTo(markersGroup);
    });

    // Auto-fit bounds if records exist
    if (filteredRecords.length > 0) {
      const bounds = L.latLngBounds(
        filteredRecords.map((r) => [r.destination.latitude, r.destination.longitude])
      );
      map.fitBounds(bounds, { padding: [40, 40], maxZoom: 10 });
    }
  }, [filteredRecords, showCarryingCapacityZone, onSelectDestination]);

  const highCount = intelligenceRecords.filter((r) => r.crowdStatus === 'HIGH').length;
  const medCount = intelligenceRecords.filter((r) => r.crowdStatus === 'MEDIUM').length;
  const lowCount = intelligenceRecords.filter((r) => r.crowdStatus === 'LOW').length;

  return (
    <div className="space-y-4">
      {/* Map Filter Controls Bar */}
      <div className="flex flex-wrap items-center justify-between gap-3 p-3.5 bg-white dark:bg-stone-900 border border-stone-200 dark:border-stone-800 rounded-2xl shadow-xs">
        <div className="flex flex-wrap items-center gap-1.5">
          <span className="text-xs font-bold text-stone-700 dark:text-stone-300 mr-1 flex items-center gap-1">
            <Filter className="h-3.5 w-3.5 text-stone-500" />
            Crowd Pressure:
          </span>

          <button
            onClick={() => setCrowdFilter('ALL')}
            className={`px-3 py-1.5 rounded-xl text-xs font-semibold transition-all cursor-pointer ${
              crowdFilter === 'ALL'
                ? 'bg-stone-900 text-white dark:bg-stone-100 dark:text-stone-900 shadow-xs'
                : 'bg-stone-100 dark:bg-stone-800 text-stone-700 dark:text-stone-300 hover:bg-stone-200'
            }`}
          >
            All Sites ({intelligenceRecords.length})
          </button>

          <button
            onClick={() => setCrowdFilter('HIGH')}
            className={`px-3 py-1.5 rounded-xl text-xs font-bold transition-all flex items-center gap-1.5 cursor-pointer ${
              crowdFilter === 'HIGH'
                ? 'bg-red-600 text-white shadow-xs'
                : 'bg-red-50 dark:bg-red-950/60 text-red-700 dark:text-red-300 border border-red-200 dark:border-red-900 hover:bg-red-100'
            }`}
          >
            <span>🔴 High Crowd</span>
            <span className="px-1.5 py-0.2 rounded-full bg-red-700/80 text-[10px] text-white">
              {highCount}
            </span>
          </button>

          <button
            onClick={() => setCrowdFilter('MEDIUM')}
            className={`px-3 py-1.5 rounded-xl text-xs font-bold transition-all flex items-center gap-1.5 cursor-pointer ${
              crowdFilter === 'MEDIUM'
                ? 'bg-emerald-600 text-white shadow-xs'
                : 'bg-emerald-50 dark:bg-emerald-950/60 text-emerald-700 dark:text-emerald-300 border border-emerald-200 dark:border-emerald-900 hover:bg-emerald-100'
            }`}
          >
            <span>🟢 Medium Crowd</span>
            <span className="px-1.5 py-0.2 rounded-full bg-emerald-700/80 text-[10px] text-white">
              {medCount}
            </span>
          </button>

          <button
            onClick={() => setCrowdFilter('LOW')}
            className={`px-3 py-1.5 rounded-xl text-xs font-bold transition-all flex items-center gap-1.5 cursor-pointer ${
              crowdFilter === 'LOW'
                ? 'bg-amber-600 text-white shadow-xs'
                : 'bg-amber-50 dark:bg-amber-950/60 text-amber-800 dark:text-amber-300 border border-amber-300 dark:border-amber-800 hover:bg-amber-100'
            }`}
          >
            <span>🟡 Low Crowd</span>
            <span className="px-1.5 py-0.2 rounded-full bg-amber-700/80 text-[10px] text-white">
              {lowCount}
            </span>
          </button>
        </div>

        <div className="flex items-center gap-2">
          <select
            value={selectedDistrictId}
            onChange={(e) => setSelectedDistrictId(e.target.value)}
            className="text-xs bg-stone-100 dark:bg-stone-800 text-stone-800 dark:text-stone-200 font-semibold px-3 py-1.5 rounded-xl border border-stone-200 dark:border-stone-700 focus:outline-none"
          >
            <option value="all">All Districts (8)</option>
            {districts.map((d) => (
              <option key={d.id} value={d.id}>
                {d.name} District
              </option>
            ))}
          </select>

          <button
            onClick={() => setShowCarryingCapacityZone(!showCarryingCapacityZone)}
            className={`px-2.5 py-1.5 rounded-xl text-xs font-medium border cursor-pointer ${
              showCarryingCapacityZone
                ? 'bg-stone-900 text-white dark:bg-stone-100 dark:text-stone-900 border-stone-900'
                : 'bg-stone-100 dark:bg-stone-800 text-stone-600 dark:text-stone-400 border-stone-200 dark:border-stone-700'
            }`}
            title="Toggle carrying capacity radius zones on the map"
          >
            Zones {showCarryingCapacityZone ? 'ON' : 'OFF'}
          </button>
        </div>
      </div>

      {/* Main Map Canvas & Interactive Inspector Layout */}
      <div className="grid grid-cols-1 lg:grid-cols-12 gap-4">
        <div className="lg:col-span-8 relative">
          <div
            ref={mapContainerRef}
            className="w-full h-[460px] sm:h-[540px] rounded-3xl border border-stone-200 dark:border-stone-800 shadow-md overflow-hidden z-0"
          />

          {/* OFFICIAL MANDATORY CROWD CLASSIFICATION LEGEND */}
          <div className="absolute bottom-4 left-4 z-10 bg-white/95 dark:bg-stone-900/95 backdrop-blur-md p-3.5 rounded-2xl border border-stone-200 dark:border-stone-800 shadow-xl max-w-xs space-y-2">
            <div className="flex items-center justify-between border-b border-stone-100 dark:border-stone-800 pb-1.5">
              <span className="text-[11px] font-extrabold uppercase tracking-wider text-stone-800 dark:text-stone-200">
                Official Crowd Classification
              </span>
              <Badge variant="outline" className="text-[9px] py-0 px-1 font-bold">
                JTDCL Live
              </Badge>
            </div>

            <div className="space-y-1.5 text-xs">
              <div className="flex items-start gap-2 p-1 rounded-lg bg-red-50/70 dark:bg-red-950/40">
                <span className="text-sm shrink-0">🔴</span>
                <div>
                  <span className="font-extrabold text-red-800 dark:text-red-300">High Crowd</span>
                  <p className="text-[10px] text-red-700 dark:text-red-400 leading-tight">
                    High tourist footfall • High visitor pressure • Overcrowding risk
                  </p>
                </div>
              </div>

              <div className="flex items-start gap-2 p-1 rounded-lg bg-emerald-50/70 dark:bg-emerald-950/40">
                <span className="text-sm shrink-0">🟢</span>
                <div>
                  <span className="font-extrabold text-emerald-800 dark:text-emerald-300">Medium Crowd</span>
                  <p className="text-[10px] text-emerald-700 dark:text-emerald-400 leading-tight">
                    Moderate tourist footfall • Manageable visitor pressure
                  </p>
                </div>
              </div>

              <div className="flex items-start gap-2 p-1 rounded-lg bg-amber-50/70 dark:bg-amber-950/40">
                <span className="text-sm shrink-0">🟡</span>
                <div>
                  <span className="font-extrabold text-amber-800 dark:text-amber-300">Low Crowd</span>
                  <p className="text-[10px] text-amber-700 dark:text-amber-400 leading-tight">
                    Low tourist footfall • Underutilized tourism potential
                  </p>
                </div>
              </div>
            </div>

            <p className="text-[9px] text-stone-500 dark:text-stone-400 italic pt-1 border-t border-stone-100 dark:border-stone-800">
              * Click any marker to view real-time carrying capacity & authority action.
            </p>
          </div>
        </div>

        {/* Selected Destination Intelligence Inspector */}
        <div className="lg:col-span-4 space-y-3">
          {selectedRecord ? (
            <Card className="p-5 rounded-3xl border border-stone-200 dark:border-stone-800 space-y-4 bg-white dark:bg-stone-900 shadow-md">
              <div className="flex items-start justify-between gap-2">
                <div>
                  <Badge
                    variant="outline"
                    className={`text-[10.5px] font-extrabold px-2.5 py-0.5 border ${selectedRecord.crowdConfig.badgeBg} ${selectedRecord.crowdConfig.badgeText} ${selectedRecord.crowdConfig.badgeBorder}`}
                  >
                    {selectedRecord.crowdStatus === 'HIGH' ? '🔴' : selectedRecord.crowdStatus === 'MEDIUM' ? '🟢' : '🟡'} {selectedRecord.crowdConfig.label}
                  </Badge>
                  <h3 className="font-extrabold text-lg text-stone-900 dark:text-stone-100 mt-1.5">
                    {selectedRecord.destination.name}
                  </h3>
                  <p className="text-xs text-stone-500">
                    📍 {selectedRecord.destination.district?.name} District • {selectedRecord.destination.category?.name}
                  </p>
                </div>

                <button
                  onClick={() => setSelectedRecord(null)}
                  className="text-stone-400 hover:text-stone-600 p-1 text-xs cursor-pointer"
                >
                  ✕
                </button>
              </div>

              {/* Status Meaning Banner */}
              <div className={`p-3 rounded-2xl text-xs leading-relaxed border ${selectedRecord.crowdConfig.badgeBg} ${selectedRecord.crowdConfig.badgeBorder}`}>
                <p className={`font-bold ${selectedRecord.crowdConfig.badgeText}`}>
                  {selectedRecord.crowdConfig.meaning}
                </p>
                <p className="text-[11px] text-stone-600 dark:text-stone-300 mt-1">
                  {selectedRecord.crowdConfig.footfallDescription}
                </p>
              </div>

              {/* Key Indicators Grid */}
              <div className="grid grid-cols-2 gap-2.5 text-xs">
                <div className="p-3 rounded-2xl bg-stone-50 dark:bg-stone-800/70 border border-stone-200/80 dark:border-stone-700">
                  <span className="text-[10px] text-stone-500 font-medium">Est. Monthly Visitors</span>
                  <div className="text-base font-extrabold text-stone-900 dark:text-stone-100 mt-0.5">
                    ~{selectedRecord.estimatedMonthlyFootfall.toLocaleString()}
                  </div>
                  <span className="text-[9.5px] text-stone-400">Demo estimate</span>
                </div>

                <div className="p-3 rounded-2xl bg-stone-50 dark:bg-stone-800/70 border border-stone-200/80 dark:border-stone-700">
                  <span className="text-[10px] text-stone-500 font-medium">Local Vendors Nearby</span>
                  <div className="text-base font-extrabold text-amber-700 dark:text-amber-400 mt-0.5 flex items-center gap-1">
                    <Store className="h-4 w-4" />
                    <span>{selectedRecord.activeVendorsNearCount} Stalls</span>
                  </div>
                  <span className="text-[9.5px] text-stone-400">Verified network</span>
                </div>
              </div>

              {/* Recommended Authority Action */}
              <div className="p-3.5 rounded-2xl bg-emerald-50/70 dark:bg-emerald-950/40 border border-emerald-200 dark:border-emerald-900/60 space-y-1.5">
                <div className="flex items-center gap-1.5 text-emerald-800 dark:text-emerald-300 text-xs font-bold">
                  <Zap className="h-3.5 w-3.5 text-emerald-600" />
                  <span>Recommended Government Action</span>
                </div>
                <p className="text-xs text-emerald-900 dark:text-emerald-200 leading-relaxed font-medium">
                  {selectedRecord.recommendedGovAction}
                </p>
              </div>

              {/* Actions */}
              <div className="flex items-center gap-2 pt-1">
                {navigate && (
                  <Button
                    size="sm"
                    onClick={() => navigate(`/destinations/${selectedRecord.destination.slug}`)}
                    className="flex-1 bg-stone-900 hover:bg-stone-800 text-white text-xs h-9 rounded-xl font-bold"
                  >
                    View Destination Details
                    <ArrowRight className="h-3.5 w-3.5 ml-1" />
                  </Button>
                )}
              </div>
            </Card>
          ) : (
            <Card className="p-6 rounded-3xl border border-stone-200 dark:border-stone-800 bg-stone-50/50 dark:bg-stone-900/50 flex flex-col items-center justify-center text-center h-full min-h-[300px] space-y-3">
              <div className="h-12 w-12 rounded-2xl bg-emerald-100 dark:bg-emerald-950/80 text-emerald-700 dark:text-emerald-300 flex items-center justify-center text-xl">
                🗺️
              </div>
              <h4 className="font-bold text-sm text-stone-800 dark:text-stone-200">
                Crowd Intelligence Inspector
              </h4>
              <p className="text-xs text-stone-500 max-w-xs leading-relaxed">
                Click any destination marker on the map to inspect real-time crowd pressure, carrying capacity, vendor benefits, and AI recommended government interventions.
              </p>
            </Card>
          )}
        </div>
      </div>
    </div>
  );
}

src/components/destination-card.tsx:
import React from 'react';
import { MapPin, Star, Users, Leaf, ArrowRight } from 'lucide-react';
import { Destination } from '../types/database';
import { Badge } from './ui/badge';
import { Card } from './ui/card';

export interface DestinationCardProps {
  key?: React.Key;
  destination: Destination;
  onClick: (slug: string) => void;
  className?: string;
}

export function DestinationCard({ destination, onClick, className }: DestinationCardProps) {
  const crowdBadgeVariant = {
    low: 'amber' as const,
    moderate: 'emerald' as const,
    high: 'destructive' as const,
    peak: 'destructive' as const,
  }[destination.crowd_status] || 'secondary';

  const crowdLabels: Record<string, string> = {
    low: '🟡 Low Crowd',
    moderate: '🟢 Medium Crowd',
    high: '🔴 High Crowd',
    peak: '🔴 High Crowd',
  };

  const handleImageError = (e: React.SyntheticEvent<HTMLImageElement, Event>) => {
    (e.target as HTMLImageElement).src =
      'https://images.unsplash.com/photo-1544735716-392fe2489ffa?w=800&auto=format&fit=crop&q=80';
  };

  return (
    <Card
      onClick={() => onClick(destination.slug)}
      className={`group overflow-hidden rounded-2xl sm:rounded-3xl transition-all duration-300 cursor-pointer flex flex-col h-full hover:-translate-y-1.5 bg-gradient-to-b from-emerald-800 via-emerald-900 to-teal-900 border border-emerald-600/60 shadow-lg hover:shadow-2xl hover:border-emerald-400/80 text-white ${
        className || ''
      }`}
    >
      {/* Image Container */}
      <div className="relative aspect-[16/10] overflow-hidden bg-stone-900 shrink-0">
        <img
          src={destination.featured_image}
          alt={destination.name}
          onError={handleImageError}
          className="h-full w-full object-cover group-hover:scale-105 transition-transform duration-500"
          loading="lazy"
        />
        <div className="absolute inset-0 bg-gradient-to-t from-black/75 via-black/25 to-transparent" />

        {/* Top Badges */}
        <div className="absolute top-3 left-3 right-3 flex items-center justify-between gap-2 pointer-events-none">
          {destination.is_eco_certified && (
            <Badge
              variant="emerald"
              className="bg-emerald-950/90 text-emerald-200 border-emerald-500/80 backdrop-blur-md gap-1 font-semibold text-[11px] shadow-sm"
            >
              <Leaf className="h-3 w-3 text-emerald-400" />
              Eco Certified
            </Badge>
          )}
          <Badge
            variant={crowdBadgeVariant}
            className="backdrop-blur-md capitalize ml-auto font-bold text-[11px] shadow-sm"
          >
            <Users className="h-3 w-3 mr-1" />
            {crowdLabels[destination.crowd_status] || destination.crowd_status}
          </Badge>
        </div>

        {/* Bottom District & Rating Overlay */}
        <div className="absolute bottom-3 left-3 right-3 flex items-center justify-between text-white pointer-events-none">
          <div className="flex items-center gap-1.5 text-xs font-medium bg-black/60 backdrop-blur-md px-2.5 py-1 rounded-lg border border-white/10">
            <MapPin className="h-3.5 w-3.5 text-emerald-400 shrink-0" />
            <span className="truncate max-w-[140px]">{destination.district?.name || 'Jharkhand'}</span>
          </div>
          <div className="flex items-center gap-1 text-xs font-bold bg-black/60 backdrop-blur-md px-2.5 py-1 rounded-lg border border-white/10 text-amber-300">
            <Star className="h-3.5 w-3.5 fill-amber-400 text-amber-400 shrink-0" />
            <span>{destination.rating.toFixed(1)}</span>
            <span className="text-[10px] text-stone-300 font-normal">({destination.review_count})</span>
          </div>
        </div>
      </div>

      {/* Card Content Body — Premium Forest Emerald Green */}
      <div className="p-5 sm:p-6 flex flex-col flex-1 justify-between gap-4 text-white">
        <div className="space-y-2">
          <h3 className="font-black tracking-tight text-lg sm:text-xl text-white group-hover:text-emerald-200 transition-colors line-clamp-1">
            {destination.name}
          </h3>
          <p className="text-xs sm:text-sm font-semibold text-emerald-300 line-clamp-1">
            {destination.tagline || destination.best_time_to_visit}
          </p>
          <p className="text-xs sm:text-sm leading-relaxed text-emerald-50/90 line-clamp-2 font-normal">
            {destination.description}
          </p>
        </div>

        {/* Tags & Explore Link */}
        <div className="pt-3.5 border-t border-emerald-700/50 flex items-center justify-between gap-2">
          <div className="flex flex-wrap gap-1.5 max-w-[70%]">
            {destination.tags.slice(0, 2).map((tag) => (
              <span
                key={tag}
                className="text-[11px] font-semibold px-2.5 py-0.5 rounded-full border bg-emerald-950/60 border-emerald-500/40 text-emerald-200"
              >
                #{tag}
              </span>
            ))}
          </div>

          <div className="flex items-center gap-1.5 text-xs sm:text-sm font-bold text-white group-hover:text-emerald-200 transition-transform group-hover:translate-x-1 shrink-0">
            <span>Explore</span>
            <ArrowRight className="h-3.5 w-3.5" />
          </div>
        </div>
      </div>
    </Card>
  );
}

src/components/digital-eco-pass.tsx:
import React, { useEffect, useState, useRef } from 'react';
import QRCode from 'qrcode';
import {
  Download,
  Printer,
  CheckCircle2,
  Leaf,
  Calendar,
  Users,
  MapPin,
  ShieldCheck,
  Award,
  Sparkles,
  QrCode as QrIcon
} from 'lucide-react';
import { Button } from './ui/button';
import { Badge } from './ui/badge';
import { Destination, LocalGuide } from '../types/database';

export interface DigitalEcoPassProps {
  bookingId: string;
  destination: Destination;
  visitorName: string;
  numberOfGuests: number;
  visitDate: string;
  guide?: LocalGuide | null;
  totalAmountInr?: number;
  status?: string;
  onClose?: () => void;
}

export function DigitalEcoPass({
  bookingId,
  destination,
  visitorName,
  numberOfGuests,
  visitDate,
  guide,
  totalAmountInr = 0,
  status = 'CONFIRMED',
  onClose,
}: DigitalEcoPassProps) {
  const [qrDataUrl, setQrDataUrl] = useState<string>('');
  const [isDownloading, setIsDownloading] = useState<boolean>(false);
  const passContainerRef = useRef<HTMLDivElement>(null);

  // Verification Payload for the QR code
  const qrPayload = [
    `EcoPass Verification`,
    `Booking ID: ${bookingId}`,
    `Destination: ${destination.name}`,
    `Visitor: ${visitorName}`,
    `Guests: ${numberOfGuests}`,
    `Date: ${visitDate}`,
    `Status: ${status}`,
    `Authority: Jharkhand Tourism Eco-Board`,
  ].join('\n');

  // Generate real QR code image
  useEffect(() => {
    let isCancelled = false;

    QRCode.toDataURL(qrPayload, {
      width: 320,
      margin: 1,
      color: {
        dark: '#064e3b', // Deep forest emerald
        light: '#ffffff',
      },
      errorCorrectionLevel: 'M',
    })
      .then((url) => {
        if (!isCancelled) {
          setQrDataUrl(url);
        }
      })
      .catch((err) => {
        console.error('Failed to generate QR Code:', err);
      });

    return () => {
      isCancelled = true;
    };
  }, [qrPayload]);

  // Format date nicely
  const formattedDate = React.useMemo(() => {
    try {
      const d = new Date(visitDate);
      if (isNaN(d.getTime())) return visitDate;
      return d.toLocaleDateString('en-IN', {
        weekday: 'short',
        day: 'numeric',
        month: 'short',
        year: 'numeric',
      });
    } catch {
      return visitDate;
    }
  }, [visitDate]);

  // Download pass as high quality PNG
  const handleDownload = async () => {
    setIsDownloading(true);
    try {
      const canvas = document.createElement('canvas');
      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      const width = 640;
      const height = 900;
      canvas.width = width;
      canvas.height = height;

      // Draw Background
      ctx.fillStyle = '#ffffff';
      ctx.fillRect(0, 0, width, height);

      // Draw Header Background
      const headerGrad = ctx.createLinearGradient(0, 0, width, 140);
      headerGrad.addColorStop(0, '#064e3b');
      headerGrad.addColorStop(1, '#047857');
      ctx.fillStyle = headerGrad;
      ctx.fillRect(0, 0, width, 130);

      // Header Text
      ctx.fillStyle = '#ecfdf5';
      ctx.font = 'bold 13px system-ui, -apple-system, sans-serif';
      ctx.letterSpacing = '2px';
      ctx.fillText('JHARKHAND TOURISM • DIGITAL ECO-PASS', 40, 42);

      ctx.fillStyle = '#ffffff';
      ctx.font = 'bold 24px system-ui, -apple-system, sans-serif';
      ctx.letterSpacing = '0px';
      ctx.fillText(destination.name, 40, 78);

      ctx.fillStyle = '#a7f3d0';
      ctx.font = '13px system-ui, -apple-system, sans-serif';
      ctx.fillText(`${destination.district?.name || 'Jharkhand'} District • Sustainable Travel Permit`, 40, 102);

      // Booking ID & Status Bar
      ctx.fillStyle = '#f0fdf4';
      ctx.fillRect(40, 150, width - 80, 54);
      ctx.strokeStyle = '#86efac';
      ctx.lineWidth = 1.5;
      ctx.strokeRect(40, 150, width - 80, 54);

      ctx.fillStyle = '#065f46';
      ctx.font = 'bold 11px system-ui, -apple-system, sans-serif';
      ctx.fillText('BOOKING ID', 55, 172);

      ctx.fillStyle = '#064e3b';
      ctx.font = 'bold 18px monospace';
      ctx.fillText(bookingId, 55, 194);

      // Status Pill
      ctx.fillStyle = '#10b981';
      ctx.beginPath();
      ctx.roundRect(width - 170, 162, 115, 30, 8);
      ctx.fill();

      ctx.fillStyle = '#ffffff';
      ctx.font = 'bold 12px system-ui, -apple-system, sans-serif';
      ctx.fillText('✓ CONFIRMED', width - 160, 182);

      // Pass Details Grid
      let curY = 240;
      const drawDetailRow = (label: string, value: string, y: number) => {
        ctx.fillStyle = '#64748b';
        ctx.font = '12px system-ui, -apple-system, sans-serif';
        ctx.fillText(label, 40, y);

        ctx.fillStyle = '#0f172a';
        ctx.font = 'bold 15px system-ui, -apple-system, sans-serif';
        ctx.fillText(value, 40, y + 20);

        ctx.strokeStyle = '#f1f5f9';
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(40, y + 30);
        ctx.lineTo(width - 40, y + 30);
        ctx.stroke();
      };

      drawDetailRow('PRIMARY VISITOR', visitorName, curY);
      curY += 48;
      drawDetailRow('DATE OF VISIT', `${formattedDate} (${visitDate})`, curY);
      curY += 48;
      drawDetailRow('GUEST CAPACITY', `${numberOfGuests} ${numberOfGuests === 1 ? 'Guest' : 'Guests'} (Permitted)`, curY);
      curY += 48;

      if (guide) {
        drawDetailRow('CERTIFIED LOCAL GUIDE', `${guide.name} (${guide.badge})`, curY);
        curY += 48;
      }

      drawDetailRow(
        'ENTRY PASS CHARGES',
        totalAmountInr === 0 ? 'Free Eco Sanctuary Entry' : `₹${totalAmountInr} INR (Paid & Verified)`,
        curY
      );
      curY += 60;

      // Draw QR Code
      if (qrDataUrl) {
        const qrImage = new Image();
        qrImage.crossOrigin = 'anonymous';
        await new Promise((resolve) => {
          qrImage.onload = resolve;
          qrImage.src = qrDataUrl;
        });

        const qrSize = 170;
        const qrX = (width - qrSize) / 2;
        ctx.fillStyle = '#f8fafc';
        ctx.fillRect(qrX - 10, curY - 10, qrSize + 20, qrSize + 20);
        ctx.strokeStyle = '#e2e8f0';
        ctx.strokeRect(qrX - 10, curY - 10, qrSize + 20, qrSize + 20);

        ctx.drawImage(qrImage, qrX, curY, qrSize, qrSize);
        curY += qrSize + 25;
      }

      // Responsible Tourism Notice
      ctx.fillStyle = '#047857';
      ctx.font = 'bold 11px system-ui, -apple-system, sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('RESPONSIBLE TOURISM PLEDGE', width / 2, curY);
      curY += 16;

      ctx.fillStyle = '#475569';
      ctx.font = 'italic 11px system-ui, -apple-system, sans-serif';
      ctx.fillText(
        '"Please follow local eco-tourism guidelines and help protect Jharkhand\'s',
        width / 2,
        curY
      );
      curY += 15;
      ctx.fillText(
        'natural and cultural heritage."',
        width / 2,
        curY
      );
      curY += 28;

      // Footer note
      ctx.fillStyle = '#94a3b8';
      ctx.font = '10px system-ui, -apple-system, sans-serif';
      ctx.fillText(
        `Digital Reservation Eco-Pass • Issued: ${new Date().toLocaleDateString('en-IN')}`,
        width / 2,
        curY
      );

      // Trigger Download
      const link = document.createElement('a');
      link.download = `EcoPass-${bookingId}.png`;
      link.href = canvas.toDataURL('image/png');
      link.click();
    } catch (err) {
      console.error('Error generating pass download:', err);
    } finally {
      setIsDownloading(false);
    }
  };

  // Print Pass
  const handlePrint = () => {
    window.print();
  };

  return (
    <div className="space-y-6 max-w-lg mx-auto">
      {/* Printable / Viewable Pass Card */}
      <div
        ref={passContainerRef}
        id="digital-eco-pass-printable"
        className="relative overflow-hidden rounded-3xl border-2 border-emerald-600/60 dark:border-emerald-500/40 bg-white dark:bg-stone-900 shadow-2xl transition-all"
      >
        {/* Pass Header Banner */}
        <div className="bg-gradient-to-r from-emerald-800 via-emerald-700 to-teal-800 p-5 sm:p-6 text-white relative">
          <div className="flex items-center justify-between gap-3 mb-2">
            <div className="flex items-center gap-2">
              <div className="h-8 w-8 rounded-xl bg-white/20 backdrop-blur-md flex items-center justify-center text-white">
                <Leaf className="h-4 w-4 text-emerald-200" />
              </div>
              <div>
                <span className="text-[10px] uppercase font-bold tracking-widest text-emerald-200 block">
                  Jharkhand Tourism
                </span>
                <span className="text-xs font-semibold text-emerald-100">
                  Digital Eco-Pass Permit
                </span>
              </div>
            </div>

            {/* CONFIRMED STATUS BADGE */}
            <div className="flex items-center gap-1.5 bg-emerald-500 text-white font-extrabold text-xs px-3 py-1.5 rounded-full shadow-md animate-in fade-in zoom-in-95">
              <CheckCircle2 className="h-3.5 w-3.5" />
              <span>{status}</span>
            </div>
          </div>

          <h3 className="text-xl sm:text-2xl font-black text-white tracking-tight mt-3">
            {destination.name}
          </h3>
          <p className="text-xs text-emerald-200 font-medium">
            {destination.district?.name || 'Jharkhand'} District • Eco-Sanctuary Pass
          </p>
        </div>

        {/* Booking ID Banner */}
        <div className="bg-emerald-50 dark:bg-emerald-950/60 border-y border-emerald-200 dark:border-emerald-800/80 px-5 sm:px-6 py-3 flex items-center justify-between">
          <div>
            <span className="text-[10px] uppercase tracking-wider font-bold text-stone-500 dark:text-stone-400 block">
              Booking ID
            </span>
            <span className="font-mono text-base sm:text-lg font-black text-emerald-800 dark:text-emerald-300">
              {bookingId}
            </span>
          </div>

          <div className="text-right">
            <span className="text-[10px] uppercase tracking-wider font-bold text-stone-500 dark:text-stone-400 block">
              Issued On
            </span>
            <span className="text-xs font-semibold text-stone-700 dark:text-stone-300">
              {new Date().toLocaleDateString('en-IN')}
            </span>
          </div>
        </div>

        {/* Main Pass Body Details */}
        <div className="p-5 sm:p-6 space-y-4">
          <div className="grid grid-cols-2 gap-3 sm:gap-4 text-xs">
            <div className="p-3 bg-stone-50 dark:bg-stone-800/60 rounded-xl border border-stone-100 dark:border-stone-800">
              <span className="text-stone-500 dark:text-stone-400 block text-[10px] font-semibold uppercase">
                Visitor Name
              </span>
              <span className="font-bold text-stone-900 dark:text-stone-100 text-sm truncate block mt-0.5">
                {visitorName}
              </span>
            </div>

            <div className="p-3 bg-stone-50 dark:bg-stone-800/60 rounded-xl border border-stone-100 dark:border-stone-800">
              <span className="text-stone-500 dark:text-stone-400 block text-[10px] font-semibold uppercase">
                Visit Date
              </span>
              <span className="font-bold text-stone-900 dark:text-stone-100 text-sm truncate block mt-0.5">
                {formattedDate}
              </span>
            </div>

            <div className="p-3 bg-stone-50 dark:bg-stone-800/60 rounded-xl border border-stone-100 dark:border-stone-800">
              <span className="text-stone-500 dark:text-stone-400 block text-[10px] font-semibold uppercase">
                Guests
              </span>
              <span className="font-bold text-stone-900 dark:text-stone-100 text-sm block mt-0.5">
                {numberOfGuests} {numberOfGuests === 1 ? 'Guest' : 'Guests'}
              </span>
            </div>

            <div className="p-3 bg-stone-50 dark:bg-stone-800/60 rounded-xl border border-stone-100 dark:border-stone-800">
              <span className="text-stone-500 dark:text-stone-400 block text-[10px] font-semibold uppercase">
                Pass Fee
              </span>
              <span className="font-bold text-emerald-700 dark:text-emerald-400 text-sm block mt-0.5">
                {totalAmountInr === 0 ? 'Free Entry' : `₹${totalAmountInr} INR`}
              </span>
            </div>
          </div>

          {guide && (
            <div className="p-3 bg-emerald-50/70 dark:bg-emerald-950/40 rounded-xl border border-emerald-200/80 dark:border-emerald-800/60 flex items-center justify-between text-xs">
              <div className="flex items-center gap-2">
                <ShieldCheck className="h-4 w-4 text-emerald-600 dark:text-emerald-400" />
                <div>
                  <span className="font-bold text-stone-900 dark:text-stone-100 block">
                    Certified Local Guide: {guide.name}
                  </span>
                  <span className="text-[11px] text-stone-500 dark:text-stone-400">
                    {guide.badge} • Daily Rate: ₹{guide.daily_rate_inr}
                  </span>
                </div>
              </div>
            </div>
          )}

          {/* QR Code Scannable Area */}
          <div className="p-4 bg-stone-50 dark:bg-stone-800/80 rounded-2xl border border-stone-200 dark:border-stone-700/80 flex flex-col sm:flex-row items-center gap-4 text-center sm:text-left">
            <div className="p-2 bg-white rounded-xl shadow-md border border-stone-200 dark:border-stone-700 shrink-0">
              {qrDataUrl ? (
                <img
                  src={qrDataUrl}
                  alt={`QR code for ${bookingId}`}
                  className="h-32 w-32 object-contain"
                />
              ) : (
                <div className="h-32 w-32 flex items-center justify-center bg-stone-100 text-stone-400">
                  <QrIcon className="h-8 w-8 animate-pulse" />
                </div>
              )}
            </div>

            <div className="space-y-1.5 flex-1">
              <div className="flex items-center justify-center sm:justify-start gap-1 text-emerald-700 dark:text-emerald-400 font-bold text-xs">
                <Sparkles className="h-3.5 w-3.5" />
                <span>Verified Scannable QR</span>
              </div>
              <p className="text-[11px] text-stone-600 dark:text-stone-400 leading-relaxed">
                Scan this QR code at the entry check-post to verify your Booking ID ({bookingId}) and tourist permit.
              </p>
              <span className="inline-block text-[10px] text-stone-400 font-medium">
                Digital Reservation Eco-Pass / Verified Demo Pass
              </span>
            </div>
          </div>

          {/* Responsible Tourism Quote */}
          <div className="p-3.5 bg-emerald-950/5 dark:bg-emerald-950/30 rounded-xl border border-emerald-500/20 text-center space-y-1">
            <span className="text-[10px] uppercase font-bold tracking-wider text-emerald-800 dark:text-emerald-300 flex items-center justify-center gap-1">
              <Leaf className="h-3 w-3" />
              Responsible Tourism Pledge
            </span>
            <p className="text-xs italic text-stone-600 dark:text-stone-400 leading-relaxed">
              "Please follow local eco-tourism guidelines and help protect Jharkhand's natural and cultural heritage."
            </p>
          </div>
        </div>
      </div>

      {/* Action Buttons: Download, Print, Close */}
      <div className="flex flex-col sm:flex-row items-center gap-3 pt-2">
        <Button
          onClick={handleDownload}
          disabled={isDownloading || !qrDataUrl}
          className="w-full sm:flex-1 bg-emerald-700 hover:bg-emerald-800 text-white font-bold py-3 text-xs gap-2 rounded-xl shadow-lg"
        >
          <Download className="h-4 w-4" />
          <span>{isDownloading ? 'Generating Image...' : 'Download Eco-Pass'}</span>
        </Button>

        <Button
          onClick={handlePrint}
          variant="outline"
          className="w-full sm:w-auto border-stone-300 dark:border-stone-700 font-bold py-3 text-xs gap-2 rounded-xl"
        >
          <Printer className="h-4 w-4" />
          <span>Print Eco-Pass</span>
        </Button>

        {onClose && (
          <Button
            onClick={onClose}
            variant="ghost"
            className="w-full sm:w-auto text-xs text-stone-500 hover:text-stone-900 dark:hover:text-white"
          >
            Done
          </Button>
        )}
      </div>
    </div>
  );
}

