import React, { useEffect, useState } from 'react';
import { Palette, Home, Users, ShieldCheck, Star, Heart, CheckCircle2 } from 'lucide-react';
import { Vendor, LocalGuide } from '../types/database';
import { fetchVendors, fetchLocalGuides } from '../services/destinations';
import { VendorCard, GuideCard } from '../components/local-card';
import { Tabs, TabsList, TabsTrigger, TabsContent } from '../components/ui/tabs';
import { Badge } from '../components/ui/badge';
import { Button } from '../components/ui/button';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription, DialogFooter } from '../components/ui/dialog';
import { Input } from '../components/ui/input';

interface DiscoverLocalPageProps {
  navigate: (path: string) => void;
}

export function DiscoverLocalPage({ navigate }: DiscoverLocalPageProps) {
  const [vendors, setVendors] = useState<Vendor[]>([]);
  const [guides, setGuides] = useState<LocalGuide[]>([]);
  const [activeTab, setActiveTab] = useState('all');
  const [loading, setLoading] = useState(true);

  // Inquire / Booking dialog state
  const [selectedVendor, setSelectedVendor] = useState<Vendor | null>(null);
  const [selectedGuide, setSelectedGuide] = useState<LocalGuide | null>(null);
  const [contactName, setContactName] = useState('');
  const [contactPhone, setContactPhone] = useState('');
  const [inquirySuccess, setInquirySuccess] = useState(false);

  useEffect(() => {
    async function loadLocalData() {
      setLoading(true);
      try {
        const [vendorsData, guidesData] = await Promise.all([
          fetchVendors(),
          fetchLocalGuides(),
        ]);
        setVendors(vendorsData);
        setGuides(guidesData);
      } catch (err) {
        console.error('Error loading local data:', err);
      } finally {
        setLoading(false);
      }
    }
    loadLocalData();
  }, []);

  const artisans = vendors.filter((v) => v.vendor_type === 'artisan_craft');
  const homestays = vendors.filter((v) => v.vendor_type === 'homestay');

  const handleInquirySubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setInquirySuccess(true);
  };

  return (
    <div className="min-h-screen bg-stone-50/50 dark:bg-stone-950 py-8 md:py-12">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 space-y-8">
        <div className="space-y-2">
          <div className="flex items-center gap-2">
            <Badge variant="emerald" className="gap-1 text-xs">
              <Palette className="h-3.5 w-3.5" />
              Community & Cultural Economy
            </Badge>
          </div>
          <h1 className="text-3xl md:text-4xl font-extrabold text-stone-900 dark:text-stone-100 tracking-tight">
            Tribal Artisans, Homestays & Native Guides
          </h1>
          <p className="text-sm md:text-base text-stone-600 dark:text-stone-400 max-w-3xl">
            Support local livelihoods directly. Browse certified Dokra brass casters, GI-tagged Sohrai painters, eco-homestays, and verified local nature trackers.
          </p>
        </div>

        {/* Tab Navigation */}
        <Tabs value={activeTab} onValueChange={setActiveTab}>
          <TabsList className="max-w-md mx-auto grid grid-cols-3">
            <TabsTrigger value="all">All Community ({vendors.length + guides.length})</TabsTrigger>
            <TabsTrigger value="artisans">Artisans & Crafts ({artisans.length})</TabsTrigger>
            <TabsTrigger value="guides">Native Guides ({guides.length})</TabsTrigger>
          </TabsList>

          {/* All Tab */}
          <TabsContent value="all" className="space-y-8 pt-4">
            <div className="space-y-4">
              <div className="flex items-center justify-between">
                <h3 className="text-xl font-bold text-stone-900 dark:text-stone-100">
                  Tribal Craft Collectives & Homestays
                </h3>
                <Button variant="link" onClick={() => setActiveTab('artisans')} className="text-xs">
                  View all artisans
                </Button>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
                {vendors.map((vendor) => (
                  <VendorCard
                    key={vendor.id}
                    vendor={vendor}
                    onBook={(v) => {
                      setSelectedVendor(v);
                      setInquirySuccess(false);
                    }}
                  />
                ))}
              </div>
            </div>

            <div className="space-y-4 pt-6 border-t border-stone-200 dark:border-stone-800">
              <div className="flex items-center justify-between">
                <h3 className="text-xl font-bold text-stone-900 dark:text-stone-100">
                  Certified Tribal Guides
                </h3>
                <Button variant="link" onClick={() => setActiveTab('guides')} className="text-xs">
                  View all guides
                </Button>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
                {guides.map((guide) => (
                  <GuideCard
                    key={guide.id}
                    guide={guide}
                    onHire={(g) => {
                      setSelectedGuide(g);
                      setInquirySuccess(false);
                    }}
                  />
                ))}
              </div>
            </div>
          </TabsContent>

          {/* Artisans Tab */}
          <TabsContent value="artisans" className="pt-4">
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
              {artisans.map((vendor) => (
                <VendorCard
                  key={vendor.id}
                  vendor={vendor}
                  onBook={(v) => {
                    setSelectedVendor(v);
                    setInquirySuccess(false);
                  }}
                />
              ))}
            </div>
          </TabsContent>

          {/* Guides Tab */}
          <TabsContent value="guides" className="pt-4">
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
              {guides.map((guide) => (
                <GuideCard
                  key={guide.id}
                  guide={guide}
                  onHire={(g) => {
                    setSelectedGuide(g);
                    setInquirySuccess(false);
                  }}
                />
              ))}
            </div>
          </TabsContent>
        </Tabs>
      </div>

      {/* Inquiry / Booking Modal */}
      <Dialog
        open={Boolean(selectedVendor || selectedGuide)}
        onOpenChange={(open) => {
          if (!open) {
            setSelectedVendor(null);
            setSelectedGuide(null);
            setInquirySuccess(false);
          }
        }}
      >
        <DialogContent
          className="max-w-md"
          onClose={() => {
            setSelectedVendor(null);
            setSelectedGuide(null);
            setInquirySuccess(false);
          }}
        >
          {inquirySuccess ? (
            <div className="py-6 text-center space-y-3">
              <CheckCircle2 className="h-14 w-14 text-emerald-600 mx-auto" />
              <DialogTitle className="text-xl font-bold">Inquiry Sent Successfully!</DialogTitle>
              <p className="text-xs text-stone-600 dark:text-stone-400">
                The local cooperative coordinator has received your details and will get in touch via SMS / WhatsApp.
              </p>
              <Button
                onClick={() => {
                  setSelectedVendor(null);
                  setSelectedGuide(null);
                  setInquirySuccess(false);
                }}
                className="w-full bg-emerald-700 mt-4"
              >
                Close
              </Button>
            </div>
          ) : (
            <form onSubmit={handleInquirySubmit}>
              <DialogHeader>
                <DialogTitle>
                  {selectedVendor
                    ? `Contact ${selectedVendor.business_name}`
                    : `Book ${selectedGuide?.name}`}
                </DialogTitle>
                <DialogDescription>
                  Direct peer-to-peer connection with verified local operators.
                </DialogDescription>
              </DialogHeader>

              <div className="space-y-4 py-3 text-xs">
                <div>
                  <label className="block text-stone-700 dark:text-stone-300 font-semibold mb-1">
                    Your Name
                  </label>
                  <Input
                    type="text"
                    value={contactName}
                    onChange={(e) => setContactName(e.target.value)}
                    placeholder="Enter your full name"
                    required
                  />
                </div>
                <div>
                  <label className="block text-stone-700 dark:text-stone-300 font-semibold mb-1">
                    Phone / WhatsApp Number
                  </label>
                  <Input
                    type="tel"
                    value={contactPhone}
                    onChange={(e) => setContactPhone(e.target.value)}
                    placeholder="+91 98765 43210"
                    required
                  />
                </div>
                <p className="text-[11px] text-stone-500">
                  Zero commission fee: 100% of payment goes directly to the local artisan / guide.
                </p>
              </div>

              <DialogFooter>
                <Button
                  type="button"
                  variant="outline"
                  onClick={() => {
                    setSelectedVendor(null);
                    setSelectedGuide(null);
                  }}
                >
                  Cancel
                </Button>
                <Button type="submit" className="bg-emerald-700 font-bold">
                  Send Booking Request
                </Button>
              </DialogFooter>
            </form>
          )}
        </DialogContent>
      </Dialog>
    </div>
  );
}

src/routes/explore.tsx:
import React, { useEffect, useState } from 'react';
import {
  Search,
  Filter,
  MapPin,
  Leaf,
  Compass,
  Sparkles,
  SlidersHorizontal,
  RefreshCw,
} from 'lucide-react';
import { Destination, Category, District } from '../types/database';
import { fetchDestinations, fetchCategories, fetchDistricts } from '../services/destinations';
import { DestinationCard } from '../components/destination-card';
import { Button } from '../components/ui/button';
import { Badge } from '../components/ui/badge';
import { Input } from '../components/ui/input';
import { Section } from '../components/section';
import { Skeleton } from '../components/ui/skeleton';

interface ExplorePageProps {
  navigate: (path: string) => void;
  initialSearch?: string;
  initialCategory?: string;
}

export function ExplorePage({
  navigate,
  initialSearch = '',
  initialCategory = 'all',
}: ExplorePageProps) {
  const [destinations, setDestinations] = useState<Destination[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [districts, setDistricts] = useState<District[]>([]);

  // Filter states
  const [searchQuery, setSearchQuery] = useState(initialSearch);
  const [selectedCategory, setSelectedCategory] = useState(initialCategory);
  const [selectedDistrict, setSelectedDistrict] = useState('all');
  const [ecoCertifiedOnly, setEcoCertifiedOnly] = useState(false);
  const [loading, setLoading] = useState(true);

  // Sync state if props change (e.g. navigation query params)
  useEffect(() => {
    if (initialSearch) setSearchQuery(initialSearch);
  }, [initialSearch]);

  useEffect(() => {
    if (initialCategory) setSelectedCategory(initialCategory);
  }, [initialCategory]);

  // Load initial dropdown options
  useEffect(() => {
    async function loadOptions() {
      try {
        const [catData, distData] = await Promise.all([
          fetchCategories(),
          fetchDistricts(),
        ]);
        setCategories(catData);
        setDistricts(distData);
      } catch (err) {
        console.error('Error loading filter options:', err);
      }
    }
    loadOptions();
  }, []);

  // Fetch destinations from data layer whenever filter states update
  useEffect(() => {
    let isCancelled = false;

    async function loadDestinations() {
      setLoading(true);
      try {
        const data = await fetchDestinations({
          categorySlug: selectedCategory !== 'all' ? selectedCategory : undefined,
          districtId: selectedDistrict !== 'all' ? selectedDistrict : undefined,
          searchQuery: searchQuery.trim() || undefined,
          ecoCertifiedOnly: ecoCertifiedOnly ? true : undefined,
        });
        if (!isCancelled) {
          setDestinations(data);
        }
      } catch (err) {
        console.error('Error loading destinations:', err);
      } finally {
        if (!isCancelled) setLoading(false);
      }
    }

    loadDestinations();

    return () => {
      isCancelled = true;
    };
  }, [selectedCategory, selectedDistrict, searchQuery, ecoCertifiedOnly]);

  const handleResetFilters = () => {
    setSearchQuery('');
    setSelectedCategory('all');
    setSelectedDistrict('all');
    setEcoCertifiedOnly(false);
  };

  return (
    <div className="min-h-screen bg-stone-50/70 dark:bg-stone-950 text-stone-900 dark:text-stone-100 py-8 md:py-12">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 space-y-8">
        {/* Header & Title */}
        <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
          <div className="space-y-2">
            <div className="flex items-center gap-2">
              <Badge variant="emerald" className="gap-1 text-xs bg-emerald-100 dark:bg-emerald-950 text-emerald-800 dark:text-emerald-300 border-emerald-300 dark:border-emerald-800 font-semibold">
                <Leaf className="h-3.5 w-3.5 text-emerald-600 dark:text-emerald-400" />
                Live Destination Catalog
              </Badge>
            </div>
            <h1 className="text-3xl md:text-4xl font-extrabold text-stone-900 dark:text-stone-100 tracking-tight">
              Explore Jharkhand Eco & Cultural Sites
            </h1>
            <p className="text-sm md:text-base text-stone-600 dark:text-stone-400 max-w-3xl">
              Browse state-wide eco-tourism hotspots, sacred waterfalls, ancient shrines, and biodiversity parks. Filter by district, theme, and eco-certification.
            </p>
          </div>
          <Button
            onClick={() => navigate('/map')}
            className="self-start sm:self-auto bg-emerald-700 hover:bg-emerald-800 text-white font-bold text-xs gap-1.5 shrink-0 shadow-md"
          >
            <Compass className="h-4 w-4 text-white" />
            <span>Explore Map</span>
          </Button>
        </div>

        {/* Filter Controls Bar */}
        <div className="p-4 sm:p-6 bg-white dark:bg-stone-900 rounded-2xl sm:rounded-3xl border border-stone-200 dark:border-stone-800 shadow-sm space-y-4">
          {/* Top Search Input */}
          <div className="relative">
            <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 h-4 w-4 text-stone-400" />
            <Input
              type="text"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              placeholder="Search by destination name, district, activities or tags..."
              className="pl-10 h-11 text-sm bg-stone-50 dark:bg-stone-800 border-stone-200 dark:border-stone-700 text-stone-900 dark:text-stone-100 placeholder:text-stone-400 rounded-xl focus:ring-2 focus:ring-emerald-500"
            />
          </div>

          {/* Category Chips Scroll */}
          <div className="flex items-center gap-2 overflow-x-auto pb-1 text-xs no-scrollbar">
            <button
              onClick={() => setSelectedCategory('all')}
              className={`px-3.5 py-1.5 rounded-full transition-all cursor-pointer shrink-0 ${
                selectedCategory === 'all'
                  ? 'bg-emerald-700 text-white font-bold shadow-sm'
                  : 'bg-stone-100 dark:bg-stone-800 text-stone-700 dark:text-stone-300 hover:bg-stone-200 dark:hover:bg-stone-700 font-medium'
              }`}
            >
              All Categories
            </button>
            {categories.map((cat) => (
              <button
                key={cat.id}
                onClick={() => setSelectedCategory(cat.slug)}
                className={`px-3.5 py-1.5 rounded-full transition-all cursor-pointer shrink-0 ${
                  selectedCategory === cat.slug
                    ? 'bg-emerald-700 text-white font-bold shadow-sm'
                    : 'bg-stone-100 dark:bg-stone-800 text-stone-700 dark:text-stone-300 hover:bg-stone-200 dark:hover:bg-stone-700 font-medium'
                }`}
              >
                {cat.name}
              </button>
            ))}
          </div>

          {/* Secondary District Dropdown & Eco Toggle */}
          <div className="flex flex-wrap items-center justify-between gap-3 pt-3 border-t border-stone-100 dark:border-stone-800 text-xs">
            <div className="flex flex-wrap items-center gap-3">
              {/* District Select */}
              <div className="flex items-center gap-2">
                <MapPin className="h-4 w-4 text-emerald-600 dark:text-emerald-400" />
                <span className="text-stone-600 dark:text-stone-400 font-medium">District:</span>
                <select
                  value={selectedDistrict}
                  onChange={(e) => setSelectedDistrict(e.target.value)}
                  className="bg-stone-50 dark:bg-stone-800 border border-stone-300 dark:border-stone-700 rounded-lg px-2.5 py-1 text-xs text-stone-900 dark:text-stone-100 focus:outline-none focus:ring-1 focus:ring-emerald-500"
                >
                  <option value="all">All Districts (8 Active)</option>
                  {districts.map((d) => (
                    <option key={d.id} value={d.id}>
                      {d.name}
                    </option>
                  ))}
                </select>
              </div>

              {/* Eco-Certified Toggle */}
              <label className="flex items-center gap-2 cursor-pointer select-none bg-emerald-50 dark:bg-emerald-950/60 border border-emerald-200 dark:border-emerald-800/80 px-2.5 py-1 rounded-lg text-emerald-800 dark:text-emerald-300 font-semibold">
                <input
                  type="checkbox"
                  checked={ecoCertifiedOnly}
                  onChange={(e) => setEcoCertifiedOnly(e.target.checked)}
                  className="rounded border-emerald-400 text-emerald-600 focus:ring-emerald-500 h-3.5 w-3.5"
                />
                <span>Eco-Certified Only</span>
              </label>
            </div>

            {/* Reset Button */}
            {(searchQuery || selectedCategory !== 'all' || selectedDistrict !== 'all' || ecoCertifiedOnly) && (
              <Button
                variant="ghost"
                size="sm"
                onClick={handleResetFilters}
                className="text-stone-500 hover:text-stone-900 dark:text-stone-400 dark:hover:text-white text-xs gap-1 h-7"
              >
                <RefreshCw className="h-3 w-3" />
                Reset Filters
              </Button>
            )}
          </div>
        </div>

        {/* Results Counter */}
        <div className="flex items-center justify-between text-xs text-stone-500 dark:text-stone-400 px-1">
          <span>
            Showing <strong className="text-stone-900 dark:text-stone-100 font-bold">{destinations.length}</strong> destinations
          </span>
          <span className="text-emerald-700 dark:text-emerald-400 font-semibold">
            Verified Jharkhand Database
          </span>
        </div>

        {/* Destination Grid */}
        {loading ? (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 lg:gap-8">
            {[1, 2, 3, 4, 5, 6].map((i) => (
              <div key={i} className="h-96 rounded-2xl bg-stone-200 dark:bg-stone-800 animate-pulse" />
            ))}
          </div>
        ) : destinations.length > 0 ? (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 lg:gap-8">
            {destinations.map((dest) => (
              <DestinationCard
                key={dest.id}
                destination={dest}
                onClick={(slug) => navigate(`/destinations/${slug}`)}
              />
            ))}
          </div>
        ) : (
          <div className="p-12 text-center rounded-2xl bg-white dark:bg-stone-900 border border-stone-200 dark:border-stone-800 space-y-3">
            <Compass className="h-12 w-12 text-stone-400 mx-auto" />
            <h3 className="text-lg font-bold text-stone-900 dark:text-stone-100">
              No destinations match your criteria
            </h3>
            <p className="text-sm text-stone-500 dark:text-stone-400 max-w-md mx-auto">
              Try adjusting your search query, removing district filters, or clearing the category selection.
            </p>
            <Button onClick={handleResetFilters} className="mt-2 bg-emerald-700 hover:bg-emerald-800 text-white font-bold">
              Clear All Filters
            </Button>
          </div>
        )}
      </div>
    </div>
  );
}

src/routes/forgot-password.tsx:
import React, { useState, useEffect } from 'react';
import { Leaf, Mail, Lock, ArrowLeft, ArrowRight, AlertCircle, CheckCircle2, RefreshCw, KeyRound, Eye, EyeOff } from 'lucide-react';
import { useAuth } from '../lib/auth-context';
import { Card } from '../components/ui/card';
import { Button } from '../components/ui/button';
import { Input } from '../components/ui/input';

interface ForgotPasswordPageProps {
  navigate: (path: string) => void;
  isResetMode?: boolean;
}

export function ForgotPasswordPage({ navigate, isResetMode = false }: ForgotPasswordPageProps) {
  const { resetPassword, updatePassword } = useAuth();

  const [email, setEmail] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);

  // Check if hash has access_token or type=recovery
  const [isRecoveryFlow, setIsRecoveryFlow] = useState(isResetMode);

  useEffect(() => {
    if (window.location.hash.includes('type=recovery') || window.location.pathname.includes('/reset-password')) {
      setIsRecoveryFlow(true);
    }
  }, []);

  const handleForgotSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setErrorMessage(null);
    setSuccessMessage(null);

    const trimmedEmail = email.trim();
    if (!trimmedEmail) {
      setErrorMessage('Please enter your email address.');
      return;
    }

    setSubmitting(true);
    try {
      const res = await resetPassword(trimmedEmail);
      if (res.success) {
        setSuccessMessage(res.message || 'Password reset link sent to your email. Please check your inbox.');
      } else {
        setErrorMessage(res.error || 'Something went wrong while requesting password reset. Please try again.');
      }
    } catch (err: any) {
      setErrorMessage('Something went wrong while requesting password reset. Please try again.');
    } finally {
      setSubmitting(false);
    }
  };

  const handleResetSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setErrorMessage(null);
    setSuccessMessage(null);

    if (newPassword.length < 6) {
      setErrorMessage('Password must be at least 6 characters long.');
      return;
    }

    if (newPassword !== confirmPassword) {
      setErrorMessage('Passwords do not match. Please re-enter your password.');
      return;
    }

    setSubmitting(true);
    try {
      const res = await updatePassword(newPassword);
      if (res.success) {
        setSuccessMessage('Your password has been reset successfully! Redirecting you to Sign In...');
        setTimeout(() => {
          navigate('/signin');
        }, 1200);
      } else {
        setErrorMessage(res.error || 'Failed to update password. Please try again.');
      }
    } catch (err: any) {
      setErrorMessage('Something went wrong while resetting your password. Please try again.');
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div className="min-h-[85vh] flex items-center justify-center px-4 py-12 bg-gradient-to-b from-stone-50 via-white to-stone-50 dark:from-stone-950 dark:via-stone-900 dark:to-stone-950">
      <div className="max-w-md w-full space-y-6">
        {/* Header Branding */}
        <div className="text-center space-y-2">
          <div
            onClick={() => navigate('/')}
            className="inline-flex items-center gap-2 cursor-pointer group"
          >
            <div className="h-10 w-10 rounded-xl bg-gradient-to-tr from-emerald-800 to-teal-600 flex items-center justify-center text-white shadow-md shadow-emerald-900/20 group-hover:scale-105 transition-transform">
              <Leaf className="h-5 w-5 text-emerald-100" />
            </div>
            <span className="font-bold text-xl tracking-tight text-stone-900 dark:text-stone-50">
              Johar Jharkhand
            </span>
          </div>

          <h1 className="text-2xl font-extrabold text-stone-900 dark:text-stone-100 pt-1">
            {isRecoveryFlow ? 'Reset Your Password' : 'Forgot Your Password?'}
          </h1>
          <p className="text-xs text-stone-500 max-w-sm mx-auto">
            {isRecoveryFlow
              ? 'Enter and confirm your new secure password below.'
              : 'Enter your registered email address and we will send you a link to reset your password.'}
          </p>
        </div>

        {/* Card Form */}
        <Card className="p-6 sm:p-8 rounded-3xl border border-stone-200 dark:border-stone-800 bg-white dark:bg-stone-900 shadow-xl space-y-5">
          {errorMessage && (
            <div className="p-3.5 bg-rose-50 dark:bg-rose-950/60 border border-rose-200 dark:border-rose-800 rounded-2xl text-rose-700 dark:text-rose-300 text-xs flex items-start gap-2.5 animate-in fade-in-50">
              <AlertCircle className="h-4 w-4 shrink-0 mt-0.5" />
              <div className="flex-1 font-medium">{errorMessage}</div>
            </div>
          )}

          {successMessage && (
            <div className="p-4 bg-emerald-50 dark:bg-emerald-950/60 border border-emerald-200 dark:border-emerald-800 rounded-2xl text-emerald-800 dark:text-emerald-200 text-xs flex items-start gap-2.5 animate-in fade-in-50">
              <CheckCircle2 className="h-4 w-4 shrink-0 text-emerald-600 mt-0.5" />
              <div className="flex-1 font-medium">{successMessage}</div>
            </div>
          )}

          {!isRecoveryFlow ? (
            <form onSubmit={handleForgotSubmit} className="space-y-4">
              <div className="space-y-1.5">
                <label className="text-xs font-bold text-stone-700 dark:text-stone-300 flex items-center gap-1.5">
                  <Mail className="h-3.5 w-3.5 text-stone-400" />
                  <span>Your Email Address</span>
                </label>
                <Input
                  type="email"
                  placeholder="name@example.com"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  autoComplete="email"
                  className="h-11 bg-stone-50 dark:bg-stone-950 border-stone-200 dark:border-stone-800 rounded-xl text-sm"
                  required
                />
              </div>

              <div className="pt-2">
                <Button
                  type="submit"
                  disabled={submitting}
                  className="w-full h-11 bg-emerald-700 hover:bg-emerald-800 text-white font-bold text-sm rounded-xl shadow-lg flex items-center justify-center gap-2 cursor-pointer transition-all"
                >
                  {submitting ? (
                    <>
                      <RefreshCw className="h-4 w-4 animate-spin" />
                      <span>Sending reset link...</span>
                    </>
                  ) : (
                    <>
                      <span>Send Password Reset Link</span>
                      <ArrowRight className="h-4 w-4" />
                    </>
                  )}
                </Button>
              </div>
            </form>
          ) : (
            <form onSubmit={handleResetSubmit} className="space-y-4">
              <div className="space-y-1.5">
                <label className="text-xs font-bold text-stone-700 dark:text-stone-300 flex items-center gap-1.5">
                  <KeyRound className="h-3.5 w-3.5 text-stone-400" />
                  <span>New Password</span>
                </label>
                <div className="relative">
                  <Input
                    type={showPassword ? 'text' : 'password'}
                    placeholder="At least 6 characters"
                    value={newPassword}
                    onChange={(e) => setNewPassword(e.target.value)}
                    className="h-11 pr-10 bg-stone-50 dark:bg-stone-950 border-stone-200 dark:border-stone-800 rounded-xl text-sm"
                    required
                  />
                  <button
                    type="button"
                    onClick={() => setShowPassword(!showPassword)}
                    className="absolute right-3 top-1/2 -translate-y-1/2 text-stone-400 hover:text-stone-600 dark:hover:text-stone-200 cursor-pointer p-1"
                  >
                    {showPassword ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
                  </button>
                </div>
              </div>

              <div className="space-y-1.5">
                <label className="text-xs font-bold text-stone-700 dark:text-stone-300 flex items-center gap-1.5">
                  <Lock className="h-3.5 w-3.5 text-stone-400" />
                  <span>Confirm New Password</span>
                </label>
                <Input
                  type={showPassword ? 'text' : 'password'}
                  placeholder="Re-enter new password"
                  value={confirmPassword}
                  onChange={(e) => setConfirmPassword(e.target.value)}
                  className="h-11 bg-stone-50 dark:bg-stone-950 border-stone-200 dark:border-stone-800 rounded-xl text-sm"
                  required
                />
              </div>

              <div className="pt-2">
                <Button
                  type="submit"
                  disabled={submitting}
                  className="w-full h-11 bg-emerald-700 hover:bg-emerald-800 text-white font-bold text-sm rounded-xl shadow-lg flex items-center justify-center gap-2 cursor-pointer transition-all"
                >
                  {submitting ? (
                    <>
                      <RefreshCw className="h-4 w-4 animate-spin" />
                      <span>Updating password...</span>
                    </>
                  ) : (
                    <>
                      <span>Update Password</span>
                      <ArrowRight className="h-4 w-4" />
                    </>
                  )}
                </Button>
              </div>
            </form>
          )}

          {/* Back to Sign In Link */}
          <div className="text-center pt-2 border-t border-stone-100 dark:border-stone-800">
            <button
              onClick={() => navigate('/signin')}
              className="inline-flex items-center gap-1 text-xs font-semibold text-stone-600 dark:text-stone-400 hover:text-emerald-700 dark:hover:text-emerald-300 cursor-pointer"
            >
              <ArrowLeft className="h-3.5 w-3.5" />
              <span>Back to Sign In</span>
            </button>
          </div>
        </Card>
      </div>
    </div>
  );
}

