                Sign In
              </Button>
            )}
          </div>
        </Card>

        {/* Tab Navigation */}
        <div className="space-y-6">
          <div className="flex flex-wrap border-b border-stone-200 dark:border-stone-800 gap-4 sm:gap-6 text-sm font-bold">
            <button
              onClick={() => setActiveTab('passes')}
